CREATE OR REPLACE FUNCTION garments_access.access_snapshot()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=(select auth.uid()); result jsonb;
begin
 if actor is null then raise exception 'Sign in required' using errcode='42501'; end if;
 if not exists(select 1 from garments_access.app_user where user_id=actor and is_active) then
  return jsonb_build_object('enabled',false,'actor',actor,'reason','Your account is not yet linked and enabled by an administrator.');
 end if;
 select jsonb_build_object('enabled',true,'actor',actor,'employeeId',u.employee_id,
 'permissions',(select coalesce(jsonb_object_agg(r.key,p.actions),'{}'::jsonb) from garments_access.app_resource r cross join lateral (
  select coalesce(jsonb_object_agg(a.action,garments_access.has_screen_permission(r.key,a.action)),'{}'::jsonb) actions
  from unnest(array['view','create','edit','delete','format','export','print']) a(action)
 ) p where r.resource_type='screen'),
 'administrator',garments_access.has_screen_permission('adminRoles','view')) into result
 from garments_access.app_user u where u.user_id=actor;
 return result;
end;
$function$
;
CREATE OR REPLACE FUNCTION garments_access.admin_snapshot()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 perform garments_access.require_administrator();
 return jsonb_build_object(
 'roles',(select coalesce(jsonb_agg(to_jsonb(r) order by r.id),'[]'::jsonb) from garments_access.app_role r),
 'resources',(select coalesce(jsonb_agg(to_jsonb(r) order by r.sort_order),'[]'::jsonb) from garments_access.app_resource r),
 'permissions',(select coalesce(jsonb_agg(to_jsonb(p)),'[]'::jsonb) from garments_access.app_role_resource_permission p),
 'accounts',(select coalesce(jsonb_agg(jsonb_build_object('user_id',u.user_id,'employee_id',u.employee_id,'is_active',u.is_active,'version',u.version,'employee_code',e.employee_code,'name',c.company_name,'role_ids',(select coalesce(jsonb_agg(ur.role_id),'[]'::jsonb) from garments_access.app_user_role ur where ur.user_id=u.user_id))),'[]'::jsonb) from garments_access.app_user u join garments_erp.employee e on e.id=u.employee_id left join garments_erp.contacts c on c.id=e.contacts_id),
 'employees',(select coalesce(jsonb_agg(jsonb_build_object('id',e.id,'employee_code',e.employee_code,'name',c.company_name)),'[]'::jsonb) from garments_erp.employee e left join garments_erp.contacts c on c.id=e.contacts_id),
 'auth_accounts',(select coalesce(jsonb_agg(jsonb_build_object('id',u.id,'phone',u.phone,'email',u.email)),'[]'::jsonb) from auth.users u),
 'audit',(select coalesce(jsonb_agg(to_jsonb(a) order by a.created_at desc),'[]'::jsonb) from (select * from garments_access.app_activity_log order by created_at desc,id desc limit 200) a)
 );
end;
$function$
;
CREATE OR REPLACE FUNCTION garments_access.archive_role(p_role_id bigint, p_expected_version bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare target garments_access.app_role;
begin
 perform pg_advisory_xact_lock(71426,1);
 perform garments_access.require_administrator();
 select * into target from garments_access.app_role where id=p_role_id for update;
 if not found then raise exception 'Role no longer exists';end if;
 if target.is_system_admin then raise exception 'The Administrator role cannot be archived';end if;
 if not target.is_active then raise exception 'Role is already archived';end if;
 if target.version is distinct from p_expected_version then raise exception 'Role changed. Reload before archiving' using errcode='40001';end if;
 if exists(select 1 from garments_access.app_user_role where role_id=p_role_id) then raise exception 'Reassign all employees before archiving, including disabled accounts';end if;
 update garments_access.app_role set is_active=false,version=version+1 where id=p_role_id;
 insert into garments_access.app_activity_log(actor_user_id,app_resource_id,action,target_type,target_id,details)
 select auth.uid(),r.id,'Archived role','app_role',p_role_id::text,jsonb_build_object('name',target.name) from garments_access.app_resource r where key='adminRoles';
end;
$function$
;
CREATE OR REPLACE FUNCTION garments_access.begin_file_upload(p_key text, p_record_id bigint, p_filename text, p_mime text, p_size bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t jsonb; g garments_erp.bucket_group; b storage.buckets; r garments_access.app_file_upload; eid bigint;
begin
 perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text,74));
 perform 1 from garments_access.app_file_route where target_key=p_key for update;
 t:=garments_access.file_record(p_key,p_record_id,'edit');
 if not (t->>'enabled')::boolean then raise exception 'Uploads are disabled for this field';end if;
 select employee_id into eid from garments_access.app_user where user_id=auth.uid() and is_active;
 if eid is null then raise exception 'Linked employee required';end if;
 if (select count(*) from garments_access.app_file_upload where created_by=auth.uid() and status='pending' and expires_at>now())>=5 then raise exception 'Finish pending uploads before adding more';end if;
 select * into strict g from garments_erp.bucket_group where "group"=t->>'group' for update;
 select * into strict b from storage.buckets where id=g.bucket_id;
 if g.removal_token is not null then raise exception 'Bucket removal is in progress';end if;
 if b.public then raise exception 'Private bucket required';end if;
 if p_filename is null or length(trim(p_filename))=0 or length(p_filename)>240 or p_filename~'[[:cntrl:]]' then raise exception 'Invalid filename';end if;
 if p_size is null or p_size<=0 or p_size>least(coalesce(b.file_size_limit,10485760),(t->>'max_bytes')::bigint,10485760) then raise exception 'File exceeds upload limit';end if;
 if p_mime is null or not ((t->'mime') ? p_mime) or (b.allowed_mime_types is not null and not(p_mime=any(b.allowed_mime_types))) then raise exception 'Unsupported file type';end if;
 insert into garments_access.app_file_upload(target_key,record_id,bucket_group_id,bucket_id,storage_path,previous_attachment_id,filename,mime_type,byte_size,created_by,employee_id)
 values(p_key,p_record_id,g.id,g.bucket_id,concat(t->>'table','/',p_record_id,'/',t->>'slot','/',gen_random_uuid()),(t->>'current')::bigint,p_filename,p_mime,p_size,auth.uid(),eid) returning * into r;
 return to_jsonb(r)||jsonb_build_object('id',r.id::text,'bucket_group_id',r.bucket_group_id::text);
end $function$
;
CREATE OR REPLACE FUNCTION garments_access.cancel_bucket_removal(p_group_id bigint, p_token uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 perform garments_access.require_administrator();
 update garments_erp.bucket_group set removal_token=null,removal_bucket_id=null where id=p_group_id and removal_token=p_token and bucket_id is not null;
end $function$
;
CREATE OR REPLACE FUNCTION garments_access.cancel_file_upload(p_ticket uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r garments_access.app_file_upload;
begin
 select * into strict r from garments_access.app_file_upload where id=p_ticket and created_by=auth.uid() for update;
 if r.status='ready' then return jsonb_build_object('ready',true);end if;
 update garments_access.app_file_upload set status='cleanup_required' where id=r.id;
 return to_jsonb(r)||jsonb_build_object('status','cleanup_required');
end $function$
;
CREATE OR REPLACE FUNCTION garments_access.create_bucket_group(p_group text, p_description text, p_mimes text[], p_max_bytes bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare bid text;gid bigint;
begin
 perform garments_access.require_administrator();
 if p_group is null or p_group!~'^[a-z][a-z0-9_]{1,47}$' then raise exception 'Use 2–48 lowercase letters, numbers or underscores for the group key';end if;
 if p_description is null or length(trim(p_description))>500 then raise exception 'Description must be at most 500 characters';end if;
 if p_max_bytes is null or p_max_bytes not in (1048576,2097152,5242880,10485760) then raise exception 'Choose a file limit up to 10 MB';end if;
 if p_mimes is null or cardinality(p_mimes)=0 or array_position(p_mimes,null) is not null or not(p_mimes<@array['application/pdf','image/jpeg','image/png','image/webp']::text[]) then raise exception 'Choose supported file types';end if;
 if exists(select 1 from garments_erp.bucket_group where "group"=p_group) then raise exception 'That group key already exists';end if;
 bid:='garments-'||replace(p_group,'_','-')||'-'||substr(gen_random_uuid()::text,1,8);
 insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values(bid,bid,false,p_max_bytes,p_mimes);
 insert into garments_erp.bucket_group("group",description,bucket_id) values(p_group,trim(p_description),bid) returning id into gid;
 insert into garments_access.app_activity_log(actor_user_id,action,target_type,target_id,details) values(auth.uid(),'Created private bucket group','bucket_group',gid::text,jsonb_build_object('group',p_group,'bucket_id',bid,'max_bytes',p_max_bytes,'mime_types',p_mimes));
 return jsonb_build_object('id',gid::text,'bucket_id',bid);
end $function$
;
CREATE OR REPLACE FUNCTION garments_access.fabric_contract()
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$ select '{"yarnTypes": {"yarn_type": ["name", "yarn_count"]}, "fabricTypes": {"fabric_type": ["name"]}, "brands": {"brand_list": ["brand", "contacts_id", "contact_purpose_id"]}, "colours": {"color_map": ["name", "pantone_code"]}, "colourMappings": {"color_map_by_brand": ["color_map_id", "brand_list_id"]}, "labDips": {"lab_dip": ["date", "edition", "color_map_by_brand_id", "dyer_id"], "lab_dip_version": ["lab_dip_id", "version", "date", "shade_card_no", "shade_card_option", "comments", "lab_dip_status_id", "attached_swatch"]}, "suppliers": {"contacts": ["company_name"], "yarn_supplier": ["contacts_id", "contact_purpose_id"], "knitter": ["contacts_id", "contact_purpose_id"], "dyer": ["contacts_id", "contact_purpose_id"]}, "orders": {"yarn_purchase_order": ["yarn_supplier_id"], "yarn_purchase_order_item": ["purchase_order_number_id", "yarn_type_id", "quantity", "rate"]}, "yarn": {"yarn_bill": ["invoice_number", "invoice_date"], "yarn_bill_item": ["yarn_bill_id", "yarn_purchase_order_item_id", "billed_quantity", "billed_rate", "billed_bags"]}, "knitting": {"knitting_bill": ["invoice_number", "invoice_date", "knitter_id"], "knitting_bill_item": ["knitting_bill_id", "yarn_bill_item_id", "fabric_type_id", "greige_gsm", "consumption", "billed_quantity", "billed_rate", "billed_rolls"]}, "programs": {"dyeing_program": ["date", "dyer_id"], "dyeing_program_item": ["dyeing_program_id", "fabric_type_id", "quantity", "lab_dip_version_id", "batch_no", "comments"]}, "dyeBills": {"dyed_fabric_bill": ["invoice_number", "invoice_date"], "dyed_fabric_item": ["dyed_fabric_bill_id", "dyeing_program_item_id", "knitting_bill_item_id", "gross_quantity", "billed_quantity", "final_quantity", "dyeing_rolls", "dyeing_rate"], "batch_no_lab_dip_version_map": ["dyed_fabric_item_id", "batch_no", "lab_dip_version_id"]}, "dyed": {}, "yarnLeft": {}, "greige": {}, "batches": {}}'::jsonb $function$
;
CREATE OR REPLACE FUNCTION garments_access.fabric_json(p_table text, p_row jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare c record; result jsonb:=p_row;
begin
 for c in select a.attname from pg_catalog.pg_attribute a where a.attrelid=pg_catalog.to_regclass('garments_erp.'||p_table) and a.atttypid='pg_catalog.int8'::pg_catalog.regtype and a.attnum>0 and not a.attisdropped loop
  if result->c.attname is not null and result->c.attname<>'null'::jsonb then result:=jsonb_set(result,array[c.attname],to_jsonb(result->>c.attname));end if;
 end loop;
 return result;
end $function$
;
CREATE OR REPLACE FUNCTION garments_access.fabric_row_in_document(p_table text, p_row jsonb, p_root_table text, p_root_id text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if p_table=p_root_table then return p_row->>'id'=p_root_id;end if;
 if p_root_table='lab_dip' and p_table='lab_dip_version' then return p_row->>'lab_dip_id'=p_root_id;end if;
 if p_root_table='yarn_purchase_order' then return p_table='yarn_purchase_order_item' and p_row->>'purchase_order_number_id'=p_root_id;end if;
 if p_root_table='yarn_bill' then return p_table='yarn_bill_item' and p_row->>'yarn_bill_id'=p_root_id;end if;
 if p_root_table='knitting_bill' then return p_table='knitting_bill_item' and p_row->>'knitting_bill_id'=p_root_id;end if;
 if p_root_table='dyeing_program' then return p_table='dyeing_program_item' and p_row->>'dyeing_program_id'=p_root_id;end if;
 if p_root_table='dyed_fabric_bill' then
  if p_table='dyed_fabric_item' then return p_row->>'dyed_fabric_bill_id'=p_root_id;end if;
  if p_table='batch_no_lab_dip_version_map' then return exists(select 1 from garments_erp.dyed_fabric_item d where d.id::text=p_row->>'dyed_fabric_item_id' and d.dyed_fabric_bill_id::text=p_root_id);end if;
 end if;
 if p_root_table=any(array['yarn_supplier','knitter','dyer']) and p_table='contacts' then return true;end if;
 return false;
end $function$
;
CREATE OR REPLACE FUNCTION garments_access.fabric_snapshot()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t text; rows jsonb; result jsonb:='{}'; fields text; keys text[]:=array(select jsonb_object_keys(garments_access.fabric_contract()));
begin
 if auth.uid() is null or not exists(select 1 from unnest(keys) k where garments_access.has_screen_permission(k,'view')) then raise exception 'Fabric access is not enabled' using errcode='42501';end if;
 for t in select distinct d.table_name from garments_access.app_db_table d join garments_access.app_resource_table rt on rt.app_db_table_id=d.id join garments_access.app_resource r on r.id=rt.app_resource_id where d.schema_name='garments_erp' and r.key=any(keys) and rt.can_view and garments_access.has_screen_permission(r.key,'view') and d.table_name=any(array['contacts','contact_purpose','brand_list','yarn_supplier','knitter','dyer','yarn_type','fabric_type','color_map','color_map_by_brand','lab_dip','lab_dip_version','lab_dip_version_status','fabric_status_list','yarn_purchase_order','yarn_purchase_order_item','yarn_bill','yarn_bill_item','knitting_bill','knitting_bill_item','dyeing_program','dyeing_program_item','dyed_fabric_bill','dyed_fabric_item','batch_no_lab_dip_version_map']) loop
  fields:=case when t='contacts' then 'jsonb_build_object(''id'',x.id::text,''company_name'',x.company_name,''updated_at'',x.updated_at)' else 'garments_access.fabric_json('||quote_literal(t)||',to_jsonb(x))' end;
  execute format('select coalesce(jsonb_agg(%s order by x.id),''[]''::jsonb) from garments_erp.%I x',fields,t) into rows;
  result:=jsonb_set(result,array[t],rows);
 end loop;
 -- Attachment metadata only for records already visible in this snapshot. Private paths stay private.
 select coalesce(jsonb_agg(jsonb_build_object('id',a.id::text,'filename',a.filename,'mime_type',a.mime_type,'file_size',a.file_size)),'[]'::jsonb) into rows from garments_erp.attachments a where a.id::text in (
 select r->>'bill_attachment' from jsonb_array_elements(coalesce(result->'yarn_bill','[]')||coalesce(result->'knitting_bill','[]')||coalesce(result->'dyed_fabric_bill','[]')) r
 union select r->>'shade_card_image_attachment' from jsonb_array_elements(coalesce(result->'lab_dip_version','[]')) r);
 return result||jsonb_build_object('attachments',rows,'_live',true);
end $function$
;
CREATE OR REPLACE FUNCTION garments_access.file_cleanup(p_ticket uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if p_ticket is null then
  perform garments_access.require_administrator();
  update garments_access.app_file_upload set status='cleanup_required' where status='pending' and expires_at<now();
  return (select coalesce(jsonb_agg(to_jsonb(u)),'[]'::jsonb) from (select id,bucket_id,storage_path from garments_access.app_file_upload where status='cleanup_required' order by created_at limit 50) u);
 end if;
 if not exists(select 1 from garments_access.app_file_upload where id=p_ticket and status='cleanup_required' and (created_by=auth.uid() or garments_access.has_screen_permission('adminRoles','view'))) then raise exception 'Cleanup not allowed' using errcode='42501';end if;
 return (select to_jsonb(u) from garments_access.app_file_upload u where id=p_ticket);
end $function$
;
CREATE OR REPLACE FUNCTION garments_access.file_cleanup_done(p_ticket uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r garments_access.app_file_upload;
begin
 select * into strict r from garments_access.app_file_upload where id=p_ticket and status='cleanup_required' for update;
 if r.created_by<>auth.uid() and not garments_access.has_screen_permission('adminRoles','view') then raise exception 'Cleanup not allowed' using errcode='42501';end if;
 if exists(select 1 from storage.objects where bucket_id=r.bucket_id and name=r.storage_path) then raise exception 'Object still exists';end if;
 update garments_access.app_file_upload set status='cancelled' where id=r.id;
end $function$
;
CREATE OR REPLACE FUNCTION garments_access.file_list(p_key text, p_record_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t jsonb;
begin
 t:=garments_access.file_record(p_key,p_record_id,'view');
 return (select coalesce(jsonb_agg(to_jsonb(a)||jsonb_build_object('id',a.id::text,'current',a.id=(t->>'current')::bigint) order by a.created_at desc),'[]'::jsonb) from garments_erp.attachments a where a.id=(t->>'current')::bigint or exists(select 1 from garments_access.app_file_upload u where u.target_key=p_key and u.record_id=p_record_id and u.attachment_id=a.id and u.status='ready'));
end $function$
;
CREATE OR REPLACE FUNCTION garments_access.file_read(p_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u garments_access.app_file_upload;t jsonb;a garments_erp.attachments;g garments_erp.bucket_group;
begin
 select * into u from garments_access.app_file_upload where attachment_id=p_id and status='ready';
 if not found then raise exception 'Attachment is not registered to a record';end if;
 t:=garments_access.file_record(u.target_key,u.record_id,'view');
 select * into strict a from garments_erp.attachments where id=p_id;
 select * into strict g from garments_erp.bucket_group where id=a.bucket_group_id;
 if exists(select 1 from storage.buckets where id=g.bucket_id and public) then raise exception 'Private bucket required';end if;
 return jsonb_build_object('bucket_id',g.bucket_id,'storage_path',a.storage_path);
end $function$
;
CREATE OR REPLACE FUNCTION garments_access.file_record(p_key text, p_id bigint, p_action text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t jsonb; row_data jsonb;
begin
 t:=garments_access.file_target(p_key);
 if not garments_access.has_screen_permission(t->>'resource',p_action) then raise exception 'No permission for this attachment' using errcode='42501';end if;
 execute format('select to_jsonb(r) from garments_erp.%I r where id=$1',t->>'table') into row_data using p_id;
 if row_data is null then raise exception 'Save the record in Supabase before attaching a file';end if;
 return t||jsonb_build_object('current',row_data->(t->>'slot'));
end $function$
;
CREATE OR REPLACE FUNCTION garments_access.file_records(p_key text, p_query text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t jsonb; result jsonb;
begin
 t:=garments_access.file_target(p_key);
 if not garments_access.has_screen_permission(t->>'resource','view') then raise exception 'No permission for these records' using errcode='42501';end if;
 execute format('select coalesce(jsonb_agg(x),''[]''::jsonb) from (select id::text as id,coalesce(%I::text,id::text) as label from garments_erp.%I where %I::text ilike $1 order by id desc limit 50) x',t->>'label',t->>'table',t->>'label') into result using '%'||left(coalesce(p_query,''),100)||'%';return result;
end $function$
;
CREATE OR REPLACE FUNCTION garments_access.file_registry()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if not exists(select 1 from garments_access.app_user where user_id=auth.uid() and is_active) then raise exception 'Enabled account required' using errcode='42501';end if;
 return (select coalesce(jsonb_agg(jsonb_build_object('id',g.id::text,'group',g."group",'description',g.description,'bucket_id',coalesce(g.bucket_id,g.removal_bucket_id),'private',not coalesce(b.public,false),'max_bytes',coalesce(b.file_size_limit,10485760),'mime',coalesce(b.allowed_mime_types,array['application/pdf','image/jpeg','image/png','image/webp']),'version',g.version,'removing',g.removal_token is not null,'route_count',(select count(*) from garments_access.app_file_route r where r.bucket_group_id=g.id),'attachment_count',(select count(*) from garments_erp.attachments a where a.bucket_group_id=g.id)) order by g.id),'[]'::jsonb) from garments_erp.bucket_group g left join storage.buckets b on b.id=g.bucket_id where b.id is not null or (g.removal_token is not null and garments_access.has_screen_permission('adminRoles','view')));
end $function$
;
CREATE OR REPLACE FUNCTION garments_access.file_routes()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb;
begin
 if not exists(select 1 from garments_access.app_user where user_id=auth.uid() and is_active) then raise exception 'Enabled account required' using errcode='42501';end if;
 select coalesce(jsonb_agg(garments_access.file_target(r.target_key) order by r.target_key),'[]'::jsonb) into result
 from garments_access.app_file_route r where garments_access.has_screen_permission(garments_access.file_target_definition(r.target_key)->>'resource','view') or garments_access.has_screen_permission('adminRoles','view');
 return result;
end $function$
;
CREATE OR REPLACE FUNCTION garments_access.file_target(p_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t jsonb;r garments_access.app_file_route;g garments_erp.bucket_group;
begin
 t:=garments_access.file_target_definition(p_key);
 select * into r from garments_access.app_file_route where target_key=p_key;
 if not found then raise exception 'Attachment route is not configured';end if;
 select * into strict g from garments_erp.bucket_group where id=r.bucket_group_id;
 return t||jsonb_build_object('group',g."group",'bucket_group_id',g.id::text,'mime',r.allowed_mime_types,'max_bytes',r.max_bytes,'enabled',r.is_active,'version',r.version);
end $function$
;
CREATE OR REPLACE FUNCTION garments_access.file_target_definition(p_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare t jsonb;
begin
 select value into t from jsonb_array_elements('[
 {"key":"yarnBill","group":"fabric_bills","resource":"yarn","table":"yarn_bill","slot":"bill_attachment","label":"invoice_number"},
 {"key":"knittingBill","group":"fabric_bills","resource":"knitting","table":"knitting_bill","slot":"bill_attachment","label":"invoice_number"},
 {"key":"dyedBill","group":"fabric_bills","resource":"dyeBills","table":"dyed_fabric_bill","slot":"bill_attachment","label":"invoice_number"},
 {"key":"workerBill","group":"job_worker_bills","resource":"jobWorkerBills","table":"job_worker_bill","slot":"bill_attachment","label":"id"},
 {"key":"itemImage","group":"items","resource":"productionItems","table":"item","slot":"image_attachment","label":"style_code"},
 {"key":"rawMaterialBill","group":"raw_material_bills","resource":"materialReceipts","table":"raw_material_check_in","slot":"bill_attachment","label":"sku"},
 {"key":"employeeDocument1","group":"employee","resource":"employees","table":"employee","slot":"supporting_document_1_upload","label":"employee_code"},
 {"key":"employeeDocument2","group":"employee","resource":"employees","table":"employee","slot":"supporting_document_2_upload","label":"employee_code"},
 {"key":"labDipShade","group":"items","resource":"labDips","table":"lab_dip_version","slot":"shade_card_image_attachment","label":"id"}
 ]'::jsonb) where value->>'key'=p_key;
 if t is null then raise exception 'Attachment field is not configured';end if;return t;
end $function$
;
CREATE OR REPLACE FUNCTION garments_access.finish_bucket_removal(p_group_id bigint, p_token uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare g garments_erp.bucket_group;
begin
 perform garments_access.require_administrator();
 select * into strict g from garments_erp.bucket_group where id=p_group_id for update;
 if g.removal_token is null or g.removal_token is distinct from p_token then raise exception 'Removal reservation changed';end if;
 if exists(select 1 from storage.buckets where id=g.removal_bucket_id) then raise exception 'Storage bucket has not been removed';end if;
 -- FK constraints still prevent removal if a reference appears unexpectedly.
 delete from garments_erp.bucket_group where id=g.id;
 insert into garments_access.app_activity_log(actor_user_id,action,target_type,target_id,details) values(auth.uid(),'Removed empty bucket group','bucket_group',g.id::text,jsonb_build_object('group',g."group",'bucket_id',g.removal_bucket_id));
end $function$
;
CREATE OR REPLACE FUNCTION garments_access.finish_file_upload(p_ticket uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r garments_access.app_file_upload;t jsonb;a garments_erp.attachments;current_id bigint;o storage.objects;
begin
 select * into strict r from garments_access.app_file_upload where id=p_ticket and created_by=auth.uid() for update;
 t:=garments_access.file_record(r.target_key,r.record_id,'edit');
 if r.status='ready' then select * into a from garments_erp.attachments where id=r.attachment_id;return to_jsonb(a)||jsonb_build_object('id',a.id::text);end if;
 if r.status<>'pending' or r.expires_at<now() then raise exception 'Upload expired or cancelled';end if;
 execute format('select %I from garments_erp.%I where id=$1 for update',t->>'slot',t->>'table') into current_id using r.record_id;
 if current_id is distinct from r.previous_attachment_id then raise exception 'Attachment changed. Reload before retrying' using errcode='40001';end if;
 select * into strict o from storage.objects where bucket_id=r.bucket_id and name=r.storage_path;
 if (o.metadata->>'size')::bigint is distinct from r.byte_size or o.metadata->>'mimetype' is distinct from r.mime_type then raise exception 'Uploaded object does not match reservation';end if;
 insert into garments_erp.attachments(bucket_group_id,storage_path,filename,mime_type,file_size,uploaded_by) values(r.bucket_group_id,r.storage_path,r.filename,r.mime_type,r.byte_size::text,r.employee_id) returning * into a;
 execute format('update garments_erp.%I set %I=$1 where id=$2',t->>'table',t->>'slot') using a.id,r.record_id;
 update garments_access.app_file_upload set status='ready',attachment_id=a.id where id=r.id;
 insert into garments_access.app_activity_log(actor_user_id,action,target_type,target_id,details) values(auth.uid(),'Attached file',t->>'table',r.record_id::text,jsonb_build_object('attachment_id',a.id::text,'group',t->>'group'));
 return to_jsonb(a)||jsonb_build_object('id',a.id::text);
end $function$
;
CREATE OR REPLACE FUNCTION garments_access.has_screen_permission(p_key text, p_action text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 select (select auth.uid()) is not null and exists (
  select 1 from garments_access.app_user u
  join garments_access.app_user_role ur on ur.user_id=u.user_id
  join garments_access.app_role role on role.id=ur.role_id and role.is_active
  join garments_access.app_resource resource on resource.key=p_key and garments_access.resource_available(resource.id)
  left join garments_access.app_role_resource_permission permission on permission.app_role_id=role.id and permission.app_resource_id=resource.id
  where u.user_id=(select auth.uid()) and u.is_active
   and p_action in ('view','create','edit','delete','format','export','print')
   and (not resource.admin_only or role.is_system_admin)
   and (role.is_system_admin or (permission.can_view and case p_action
    when 'view' then permission.can_view when 'create' then permission.can_create
    when 'edit' then permission.can_edit when 'delete' then permission.can_delete
    when 'format' then permission.can_format when 'export' then permission.can_export
    when 'print' then permission.can_print else false end))
 );
$function$
;
CREATE OR REPLACE FUNCTION garments_access.prepare_bucket_removal(p_group_id bigint, p_version bigint, p_confirm text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare g garments_erp.bucket_group;bid text;token uuid;
begin
 perform garments_access.require_administrator();
 select * into strict g from garments_erp.bucket_group where id=p_group_id for update;
 if g.version is distinct from p_version then raise exception 'Bucket settings changed. Reload first' using errcode='40001';end if;
 if p_confirm is distinct from g."group" then raise exception 'Type the exact group key to confirm removal';end if;
 bid:=coalesce(g.bucket_id,g.removal_bucket_id);
 if bid is null then raise exception 'Bucket reference is missing';end if;
 if exists(select 1 from garments_access.app_file_route where bucket_group_id=g.id) then raise exception 'Reassign every upload route before removing this bucket';end if;
 if exists(select 1 from garments_erp.attachments where bucket_group_id=g.id) then raise exception 'Attachment references prevent removal';end if;
 if exists(select 1 from garments_access.app_file_upload where bucket_group_id=g.id or bucket_id=bid) then raise exception 'Upload or upload-history references prevent removal';end if;
 if exists(select 1 from storage.objects where bucket_id=bid) then raise exception 'Bucket contains files and cannot be removed';end if;
 token:=coalesce(g.removal_token,gen_random_uuid());
 update garments_erp.bucket_group set removal_token=token,removal_bucket_id=bid where id=g.id;
 return jsonb_build_object('id',g.id::text,'bucket_id',bid,'token',token);
end $function$
;
CREATE OR REPLACE FUNCTION garments_access.require_administrator()
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if not garments_access.has_screen_permission('adminRoles','view') then
  raise exception 'Administrator access required' using errcode='42501';
 end if;
end;
$function$
;
CREATE OR REPLACE FUNCTION garments_access.resource_available(p_id bigint)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
 with recursive ancestry as (
  select r.id,r.parent_resource_id,r.is_active,array[r.id] as path from garments_access.app_resource r where r.id=p_id
  union all
  select r.id,r.parent_resource_id,r.is_active,a.path||r.id from garments_access.app_resource r join ancestry a on r.id=a.parent_resource_id where not r.id=any(a.path)
 ) select coalesce(bool_and(is_active) and not exists(select 1 from ancestry a where a.parent_resource_id=any(a.path)),false) from ancestry;
$function$
;
CREATE OR REPLACE FUNCTION garments_access.save_account_access(p_user_id uuid, p_employee_id bigint, p_role_ids bigint[], p_enabled boolean, p_expected_version bigint DEFAULT NULL::bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare account garments_access.app_user;
begin
 perform pg_advisory_xact_lock(71426,1);
 perform garments_access.require_administrator();
 if p_enabled is null or coalesce(cardinality(p_role_ids),0)=0 then raise exception 'Choose at least one role and an account status'; end if;
 if exists(select 1 from unnest(p_role_ids) id where not exists(select 1 from garments_access.app_role r where r.id=id and r.is_active)) then raise exception 'Choose active roles'; end if;
 select * into account from garments_access.app_user where user_id=p_user_id for update;
 if found then
  if p_expected_version is distinct from account.version then raise exception 'Account changed. Reload before saving' using errcode='40001'; end if;
  if account.employee_id<>p_employee_id then raise exception 'An account cannot be moved to a different employee'; end if;
  update garments_access.app_user set is_active=p_enabled,version=version+1 where user_id=p_user_id;
 else
  if p_expected_version is not null then raise exception 'Account no longer exists'; end if;
  insert into garments_access.app_user(user_id,employee_id,is_active,created_by) values(p_user_id,p_employee_id,p_enabled,auth.uid());
 end if;
 delete from garments_access.app_user_role where user_id=p_user_id;
 insert into garments_access.app_user_role(user_id,role_id,created_by) select p_user_id,id,auth.uid() from (select distinct unnest(p_role_ids) id) r;
 if not exists(select 1 from garments_access.app_user u join garments_access.app_user_role ur on ur.user_id=u.user_id join garments_access.app_role r on r.id=ur.role_id where u.is_active and r.is_active and r.is_system_admin) then raise exception 'Keep at least one active Administrator'; end if;
 insert into garments_access.app_activity_log(actor_user_id,app_resource_id,action,target_type,target_id,details)
 select auth.uid(),r.id,'Updated account access','app_user',p_user_id::text,jsonb_build_object('employee_id',p_employee_id,'enabled',p_enabled,'role_ids',p_role_ids) from garments_access.app_resource r where key='adminAccess';
end;
$function$
;
CREATE OR REPLACE FUNCTION garments_access.save_bucket_group(p_group_id bigint, p_version bigint, p_description text, p_max_bytes bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare g garments_erp.bucket_group;
begin
 perform garments_access.require_administrator();
 if p_description is null or length(trim(p_description))>500 or p_max_bytes not in (1048576,2097152,5242880,10485760) or p_max_bytes is null then raise exception 'Invalid bucket settings';end if;
 select * into strict g from garments_erp.bucket_group where id=p_group_id for update;
 if g.version is distinct from p_version then raise exception 'Settings changed. Reload before saving' using errcode='40001';end if;
 if not exists(select 1 from storage.buckets where id=g.bucket_id and not public) then raise exception 'Private bucket required';end if;
 update garments_erp.bucket_group set description=trim(p_description),version=version+1 where id=g.id;
 update storage.buckets set file_size_limit=p_max_bytes where id=g.bucket_id;
 insert into garments_access.app_activity_log(actor_user_id,action,target_type,target_id,details) values(auth.uid(),'Updated bucket group','bucket_group',g.id::text,jsonb_build_object('max_bytes',p_max_bytes));
end $function$
;
CREATE OR REPLACE FUNCTION garments_access.save_fabric_document(p_resource text, p_root jsonb, p_action text, p_changes jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare contract jsonb:=garments_access.fabric_contract(); root_table text:=p_root->>'table'; root_id text:=p_root->>'id'; original_root text:=p_root->>'id'; change jsonb; t text; rid text; vals jsonb; oldrow jsonb; actual jsonb; fields jsonb; col text; columns_sql text; select_sql text; assignments text; created_id text; mapped jsonb:='{}'; entry record; delete_pass boolean; root_expected jsonb:=p_root->'before'; root_actual jsonb; permitted_roots text[]; changed_dyed text[]; changed_program text[];
begin
 if p_action not in ('create','edit') or not (contract ? p_resource) or jsonb_typeof(p_changes)<>'array' or jsonb_array_length(p_changes)>500 or jsonb_array_length(p_changes)=0 then raise exception 'Invalid Fabric command';end if;
 if not garments_access.has_screen_permission(p_resource,p_action) then raise exception 'This account cannot save this record' using errcode='42501';end if;
 permitted_roots:=case p_resource when 'suppliers' then array['yarn_supplier','knitter','dyer'] when 'labDips' then array['lab_dip'] when 'orders' then array['yarn_purchase_order'] when 'yarn' then array['yarn_bill'] when 'knitting' then array['knitting_bill'] when 'programs' then array['dyeing_program'] when 'dyeBills' then array['dyed_fabric_bill'] else array(select jsonb_object_keys(contract->p_resource)) end;
 if not root_table=any(permitted_roots) or root_id is null then raise exception 'Invalid document scope';end if;
 -- All portal Fabric writers serialize; source-balance checks and multi-row writes are atomic.
 perform pg_catalog.pg_advisory_xact_lock(741208531);
 if p_action='edit' then
  if root_id!~'^[0-9]+$' then raise exception 'Invalid record identity';end if;
  execute format('select to_jsonb(x) from garments_erp.%I x where id=$1::bigint for update',root_table) into root_actual using root_id;
  if root_actual is null or garments_access.fabric_json(root_table,root_actual) is distinct from root_expected then raise exception 'This document changed. Reload and review it again.' using errcode='40001';end if;
 elsif root_id!~'^[0-9a-f-]{36}$' then raise exception 'New records require a temporary identity';end if;
 if exists(select 1 from jsonb_array_elements(p_changes) c where jsonb_typeof(c)<>'object' or not (c ?& array['table','id','before','values']) or c->>'id' is null or c->>'table' is null) then raise exception 'Malformed document change';end if;
 -- Updates/inserts in client contract dependency order. Deletes run in reverse afterwards.
 foreach delete_pass in array array[false,true] loop
 for change in select value from jsonb_array_elements(p_changes) with ordinality c(value,n) where (value->'values'='null'::jsonb)=delete_pass order by case when delete_pass then -n else n end loop
  t:=change->>'table';rid:=change->>'id';oldrow:=change->'before';vals:=change->'values';fields:=contract->p_resource->t;
  if fields is null then raise exception 'Table is outside this screen';end if;
  if vals<>'null'::jsonb then
   if jsonb_typeof(vals)<>'object' or exists(select 1 from jsonb_object_keys(vals) k where not fields ? k) then raise exception 'Field is outside the writable contract';end if;
   for entry in select key,value from jsonb_each_text(vals) loop
    if mapped ? entry.value then vals:=jsonb_set(vals,array[entry.key],mapped->entry.value);end if;
   end loop;
   for entry in select e.key,e.value from jsonb_each_text(vals) e join information_schema.columns c on c.table_schema='garments_erp' and c.table_name=t and c.column_name=e.key where c.data_type in ('numeric','integer') and e.value is not null loop if entry.value::numeric<0 then raise exception 'Quantities, weights and rates cannot be negative';end if;end loop;
   if t='lab_dip_version' and coalesce((vals->>'attached_swatch')::boolean,false) then vals:=vals||jsonb_build_object('shade_card_no',null,'shade_card_option',null,'lab_dip_status_id',(select id::text from garments_erp.lab_dip_version_status where sort_order=4));end if;
  end if;
  if oldrow<>'null'::jsonb then
   if rid!~'^[0-9]+$' then raise exception 'Invalid existing identity';end if;
   execute format('select to_jsonb(x) from garments_erp.%I x where id=$1::bigint for update',t) into actual using rid;
   if actual is null or garments_access.fabric_json(t,actual) is distinct from oldrow then raise exception 'A linked record changed. Reload and review again.' using errcode='40001';end if;
   if not garments_access.fabric_row_in_document(t,actual,root_table,root_id) then raise exception 'Record belongs to another document';end if;
   if t='contacts' then raise exception 'Edit existing shared company details from Contacts';end if;
   if delete_pass then
    if t=root_table or t=any(array['contacts','lab_dip','lab_dip_version']) then raise exception 'This record cannot be removed here';end if;
    execute format('delete from garments_erp.%I where id=$1::bigint',t) using rid;
   else
    if not garments_access.fabric_row_in_document(t,vals||jsonb_build_object('id',rid),root_table,root_id) then raise exception 'Cannot move a row between documents';end if;
    select string_agg(format('%I=v.%I',key,key),',') into assignments from jsonb_object_keys(vals) key;
    execute format('update garments_erp.%I x set %s from jsonb_populate_record(null::garments_erp.%I,$1) v where x.id=$2::bigint',t,assignments,t) using vals,rid;
   end if;
  else
   if mapped ? rid then raise exception 'Duplicate temporary identity';end if;
   if delete_pass or rid!~'^[0-9a-f-]{36}$' then raise exception 'Invalid new record';end if;
   if not garments_access.fabric_row_in_document(t,vals||jsonb_build_object('id',rid),root_table,case when t=root_table then original_root else root_id end) then raise exception 'New row is outside the document';end if;
   select string_agg(format('%I',key),','),string_agg(format('v.%I',key),',') into columns_sql,select_sql from jsonb_object_keys(vals) key;
   execute format('insert into garments_erp.%I (%s) select %s from jsonb_populate_record(null::garments_erp.%I,$1) v returning id::text',t,columns_sql,select_sql,t) into created_id using vals;
   mapped:=mapped||jsonb_build_object(rid,created_id);if t=root_table then root_id:=created_id;end if;
  end if;
 end loop;
 end loop;
 if p_action='create' and not (mapped ? original_root) then raise exception 'The new document header is missing';end if;
 if p_resource='suppliers' then
  for change in select value from jsonb_array_elements(p_changes) where value->>'table'='contacts' loop
   if not exists(select 1 from jsonb_array_elements(p_changes) r where r->>'table'=root_table and r->'values'->>'contacts_id'=change->>'id') then raise exception 'New company must be assigned to this supplier';end if;
  end loop;
 end if;
 execute format('update garments_erp.%I set updated_at=clock_timestamp() where id=$1::bigint',root_table) using root_id;
 if root_table=any(array['yarn_purchase_order','yarn_bill','knitting_bill','dyeing_program','dyed_fabric_bill','lab_dip']) then
  t:=case root_table when 'yarn_purchase_order' then 'yarn_purchase_order_item' when 'yarn_bill' then 'yarn_bill_item' when 'knitting_bill' then 'knitting_bill_item' when 'dyeing_program' then 'dyeing_program_item' when 'dyed_fabric_bill' then 'dyed_fabric_item' else 'lab_dip_version' end;
  col:=case root_table when 'yarn_purchase_order' then 'purchase_order_number_id' else root_table||'_id' end;
  execute format('select to_jsonb(count(*)) from garments_erp.%I where %I=$1::bigint',t,col) into actual using root_id;
  if actual='0'::jsonb then raise exception 'A document must contain at least one line or version';end if;
 end if;
 -- Weight gain and shortage are allowed. Only source identity/type compatibility is checked.
 select coalesce(array_agg(distinct ref) filter(where ref is not null),array[]::text[]) into changed_dyed from (select coalesce(mapped->>(c->>'id'),c->>'id') ref from jsonb_array_elements(p_changes) c where c->>'table'='dyed_fabric_item' and c->'values'<>'null'::jsonb and exists(select 1 from unnest(array['billed_quantity','gross_quantity','final_quantity','knitting_bill_item_id','dyeing_program_item_id']) f where c->'before'->f is distinct from c->'values'->f)) q;
 select coalesce(array_agg(distinct ref) filter(where ref is not null),array[]::text[]) into changed_program from (select coalesce(mapped->>(c->>'id'),c->>'id') ref from jsonb_array_elements(p_changes) c where c->>'table'='dyeing_program_item' and c->'values'<>'null'::jsonb and exists(select 1 from unnest(array['fabric_type_id']) f where c->'before'->f is distinct from c->'values'->f)) q;
 if exists(select 1 from garments_erp.dyed_fabric_item d join garments_erp.dyeing_program_item p on p.id=d.dyeing_program_item_id join garments_erp.knitting_bill_item k on k.id=d.knitting_bill_item_id where (d.id::text=any(changed_dyed) or p.id::text=any(changed_program)) and p.fabric_type_id<>k.fabric_type_id) then raise exception 'The changed dyeing program fabric type does not match its knitted source.';end if;
 set constraints all immediate;
 return garments_access.fabric_snapshot();
end $function$
;
CREATE OR REPLACE FUNCTION garments_access.save_file_route(p_key text, p_group_id bigint, p_mimes text[], p_max_bytes bigint, p_enabled boolean, p_version bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r garments_access.app_file_route;t jsonb;g garments_erp.bucket_group;b storage.buckets;
begin
 perform garments_access.require_administrator();
 t:=garments_access.file_target_definition(p_key);
 select * into strict r from garments_access.app_file_route where target_key=p_key for update;
 if r.version is distinct from p_version then raise exception 'Route changed. Reload before saving' using errcode='40001';end if;
 select * into strict g from garments_erp.bucket_group where id=p_group_id for update;
 select * into strict b from storage.buckets where id=g.bucket_id;
 if g.removal_token is not null then raise exception 'Bucket removal is in progress';end if;
 if b.public then raise exception 'Choose a private bucket group';end if;
 if p_mimes is null or cardinality(p_mimes)=0 or array_position(p_mimes,null) is not null or not(p_mimes<@array['application/pdf','image/jpeg','image/png','image/webp']::text[]) then raise exception 'Choose supported file types';end if;
 if b.allowed_mime_types is not null and not(p_mimes<@b.allowed_mime_types) then raise exception 'File types exceed the bucket rules';end if;
 if p_key in ('itemImage','labDipShade') and 'application/pdf'=any(p_mimes) then raise exception 'This image attachment requires image types';end if;
 if p_max_bytes is null or p_max_bytes<=0 or p_max_bytes>least(coalesce(b.file_size_limit,10485760),10485760) or p_enabled is null then raise exception 'File limit exceeds the destination bucket limit';end if;
 if exists(select 1 from garments_access.app_file_upload where target_key=p_key and status='pending' and expires_at>now()) then raise exception 'An upload is in progress. Retry after it finishes';end if;
 update garments_access.app_file_route set bucket_group_id=p_group_id,allowed_mime_types=p_mimes,max_bytes=p_max_bytes,is_active=p_enabled,version=version+1 where target_key=p_key;
 insert into garments_access.app_activity_log(actor_user_id,action,target_type,target_id,details) values(auth.uid(),'Updated upload route','file_route',p_key,jsonb_build_object('bucket_group_id',p_group_id::text,'mime_types',p_mimes,'max_bytes',p_max_bytes,'enabled',p_enabled));
end $function$
;
CREATE OR REPLACE FUNCTION garments_access.save_role(p_input jsonb, p_expected_version bigint DEFAULT NULL::bigint)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare role_id bigint; old_role garments_access.app_role; entry record; resource garments_access.app_resource;
begin
 perform pg_advisory_xact_lock(71426,1);
 perform garments_access.require_administrator();
 if nullif(trim(p_input->>'name'),'') is null then raise exception 'Role name is required'; end if;
 if p_input ? 'id' and p_input->>'id' is not null then
  role_id:=(p_input->>'id')::bigint;
  select * into old_role from garments_access.app_role where id=role_id for update;
  if not found then raise exception 'Role no longer exists'; end if;
  if old_role.is_system_admin then raise exception 'Administrator role is protected'; end if;
  if p_expected_version is distinct from old_role.version then raise exception 'Role changed. Reload before saving' using errcode='40001'; end if;
  update garments_access.app_role set name=trim(p_input->>'name'),description=coalesce(p_input->>'description',''),version=version+1 where id=role_id;
 else
  insert into garments_access.app_role(key,name,description) values ('custom:'||gen_random_uuid()::text,trim(p_input->>'name'),coalesce(p_input->>'description','')) returning id into role_id;
 end if;
 -- Validate every submitted resource/action before replacing grants.
 for entry in select key,value from jsonb_each(coalesce(p_input->'permissions','{}'::jsonb)) loop
  select * into resource from garments_access.app_resource where key=entry.key and resource_type='screen';
  if not found then raise exception 'Unknown screen: %',entry.key; end if;
  if jsonb_typeof(entry.value)<>'object' then raise exception 'Invalid permissions'; end if;
  if exists(select 1 from jsonb_each(entry.value) a where a.key not in ('view','create','edit','delete','format','export','print') or jsonb_typeof(a.value)<>'boolean') then raise exception 'Invalid permission action'; end if;
  if resource.admin_only and exists(select 1 from jsonb_each(entry.value) a where a.value='true'::jsonb) then raise exception 'Administration is reserved for Administrator accounts'; end if;
  if coalesce((entry.value->>'delete')::boolean,false) then raise exception 'Deletion is not available in this pilot'; end if;
 end loop;
 delete from garments_access.app_role_resource_permission where app_role_id=role_id;
 insert into garments_access.app_role_resource_permission(app_role_id,app_resource_id,can_view,can_create,can_edit,can_delete,can_format,can_export,can_print)
 select role_id,r.id,coalesce((p.value->>'view')::boolean,false),coalesce((p.value->>'create')::boolean,false),coalesce((p.value->>'edit')::boolean,false),false,coalesce((p.value->>'format')::boolean,false),coalesce((p.value->>'export')::boolean,false),coalesce((p.value->>'print')::boolean,false)
 from jsonb_each(coalesce(p_input->'permissions','{}'::jsonb)) p join garments_access.app_resource r on r.key=p.key;
 insert into garments_access.app_activity_log(actor_user_id,app_resource_id,action,target_type,target_id,details)
 select auth.uid(),r.id,case when old_role.id is null then 'Created role' else 'Updated role' end,'app_role',role_id::text,jsonb_build_object('name',trim(p_input->>'name')) from garments_access.app_resource r where key='adminRoles';
 return role_id;
end;
$function$
;
CREATE OR REPLACE FUNCTION garments_access.stamp_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if TG_OP='INSERT' then NEW.updated_at:=clock_timestamp();
 elsif (to_jsonb(NEW)-'updated_at') is distinct from (to_jsonb(OLD)-'updated_at') then NEW.updated_at:=clock_timestamp();
 else NEW.updated_at:=OLD.updated_at;
 end if;
 return NEW;
end$function$
;
CREATE OR REPLACE FUNCTION garments_erp.check_lab_dip_traceability()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if exists(select 1 from garments_erp.dyed_fabric_item d left join garments_erp.batch_no_lab_dip_version_map b on b.dyed_fabric_item_id=d.id where b.id is null) then raise exception 'Every dyed-fabric item requires one batch mapping';end if;
 if exists(select 1 from garments_erp.batch_no_lab_dip_version_map b join garments_erp.dyed_fabric_item d on d.id=b.dyed_fabric_item_id join garments_erp.dyeing_program_item i on i.id=d.dyeing_program_item_id where i.lab_dip_version_id<>b.lab_dip_version_id) then raise exception 'Batch and originating program must reference the same lab-dip version';end if;
 if exists(select 1 from garments_erp.dyeing_program_item i join garments_erp.dyeing_program p on p.id=i.dyeing_program_id join garments_erp.lab_dip_version v on v.id=i.lab_dip_version_id join garments_erp.lab_dip l on l.id=v.lab_dip_id where p.dyer_id is distinct from l.dyer_id) then raise exception 'Lab-dip dyer must match the program dyer';end if;
 if exists(select 1 from garments_erp.dyeing_program_item i join garments_erp.batch_no_lab_dip_version_map b on b.batch_no=i.batch_no where i.lab_dip_version_id<>b.lab_dip_version_id) then raise exception 'Previous batch must use the selected lab-dip version';end if;
 if exists(select 1 from garments_erp.dyeing_program_item i join garments_erp.batch_no_lab_dip_version_map b on b.batch_no=i.batch_no join garments_erp.dyed_fabric_item d on d.id=b.dyed_fabric_item_id where d.dyeing_program_item_id=i.id) then raise exception 'A program cannot use its own output as a previous batch';end if;
 if exists(select 1 from garments_erp.variant_item vi join garments_erp.item_part ip on ip.id=vi.item_part_id join garments_erp.item it on it.id=ip.item_id join garments_erp.lab_dip l on l.id=vi.lab_dip_id join garments_erp.color_map_by_brand cm on cm.id=l.color_map_by_brand_id where it.brand_id is distinct from cm.brand_list_id) then raise exception 'Selected lab dip must match the item brand';end if;
 return null;
end$function$
;
CREATE OR REPLACE FUNCTION garments_erp.check_production_variant_links()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if exists(select 1 from garments_erp.variant_item_per_job link join garments_erp.job j on j.id=link.job_id join garments_erp.variant_item vi on vi.id=link.variant_item_id where j.item_part_id<>vi.item_part_id) then raise exception 'Job variants must belong to the job item part';end if;
 if exists(select 1 from garments_erp.stage_pieces p join garments_erp.variant_item_per_job link on link.id=p.variant_item_per_job_id join garments_erp.variant_item vi on vi.id=link.variant_item_id join garments_erp.item_part ip on ip.id=vi.item_part_id join garments_erp.item_size_list sz on sz.id=p.item_size_list_id where ip.item_id<>sz.item_id) then raise exception 'Stage size must belong to the job item';end if;
 if exists(select 1 from garments_erp.stage_pieces p join garments_erp.variant_item_per_job link on link.id=p.variant_item_per_job_id join garments_erp.job j on j.id=link.job_id join garments_erp.stage s on s.id=j.stage_id where s.pp_stage or not s.track_pieces) then raise exception 'This stage does not track production pieces';end if;
 if exists(select 1 from garments_erp.challan_job_item_pieces p join garments_erp.challan_job_item ci on ci.id=p.challan_job_item_id join garments_erp.variant_item vi on vi.id=p.variant_item_id join garments_erp.item_part ip on ip.id=vi.item_part_id join garments_erp.item_size_list sz on sz.id=p.item_size_list_id where ip.item_id<>sz.item_id or not exists(select 1 from garments_erp.variant_item_per_job link where link.job_id=ci.job_id and link.variant_item_id=vi.id)) then raise exception 'Challan variant and size must belong to its job';end if;
 return null;
end$function$
;
CREATE OR REPLACE FUNCTION garments_erp.generate_challan_number()
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE v_year integer; v_fy text; v_number bigint;
BEGIN
 v_year := extract(year from CURRENT_DATE)::integer - CASE WHEN extract(month from CURRENT_DATE)<4 THEN 1 ELSE 0 END;
 v_fy := right(v_year::text,2)||'-'||right((v_year+1)::text,2);
 INSERT INTO garments_erp.document_number_counter AS c(document_type,financial_year,last_number)
 VALUES ('SCC',v_fy,1)
 ON CONFLICT(document_type,financial_year) DO UPDATE SET last_number=c.last_number+1
 RETURNING last_number INTO v_number;
 IF v_number > 9999 THEN RAISE EXCEPTION 'Challan counter capacity exceeded in %',v_fy; END IF;
 RETURN 'SCC/'||lpad(v_number::text,4,'0')||'/'||v_fy;
END;
$function$
;
CREATE OR REPLACE FUNCTION garments_erp.generate_dyeing_program_number()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
    fy_start integer;
    fy text;
    next_num bigint;
BEGIN
    fy_start = CASE
        WHEN EXTRACT(MONTH FROM CURRENT_DATE) >= 4
        THEN CAST(EXTRACT(YEAR FROM CURRENT_DATE) AS integer)
        ELSE CAST(EXTRACT(YEAR FROM CURRENT_DATE) AS integer) - 1
    END;

    fy = RIGHT(CAST(fy_start AS text), 2) || '-' || RIGHT(CAST(fy_start + 1 AS text), 2);

    INSERT INTO garments_erp.document_number_counter AS c
        (document_type, financial_year, last_number)
    VALUES ('SCD', fy, 1)
    ON CONFLICT (document_type, financial_year)
    DO UPDATE SET last_number = c.last_number + 1
    RETURNING c.last_number INTO next_num;

    NEW.program_number = 'SCD/' || LPAD(CAST(next_num AS text), 3, '0') || '/' || fy;

    RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION garments_erp.generate_employee_code()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_number bigint;
BEGIN
    IF NEW.employee_code IS NULL
       OR btrim(NEW.employee_code) = '' THEN

        v_number := nextval(
            'garments_erp.employee_code_seq'::regclass
        );

        IF v_number > 99999 THEN
            RAISE EXCEPTION
                'Employee code capacity exceeded: SCE-99999';
        END IF;

        NEW.employee_code :=
            'SCE-' || lpad(v_number::text, 5, '0');
    END IF;

    RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION garments_erp.generate_job_code(p_stage_id bigint)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE v_abbr text; v_year integer; v_fy text; v_number bigint;
BEGIN
 SELECT s.abbr INTO v_abbr FROM garments_erp.stage s WHERE s.id=p_stage_id FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Stage % does not exist', p_stage_id; END IF;
 IF v_abbr IS NULL OR btrim(v_abbr)='' THEN RAISE EXCEPTION 'Stage abbreviation is required'; END IF;
 v_year := extract(year from CURRENT_DATE)::integer - CASE WHEN extract(month from CURRENT_DATE)<4 THEN 1 ELSE 0 END;
 v_fy := right(v_year::text,2)||'-'||right((v_year+1)::text,2);
 INSERT INTO garments_erp.document_number_counter AS c(document_type,financial_year,last_number)
 VALUES ('JOB:'||v_abbr,v_fy,1)
 ON CONFLICT(document_type,financial_year) DO UPDATE SET last_number=c.last_number+1
 RETURNING last_number INTO v_number;
 IF v_number > 99999 THEN RAISE EXCEPTION 'Job counter capacity exceeded for stage % in %',v_abbr,v_fy; END IF;
 RETURN v_abbr||'/'||lpad(v_number::text,5,'0')||'/'||v_fy;
END;
$function$
;
CREATE OR REPLACE FUNCTION garments_erp.generate_raw_material_po_number()
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE y integer; fy text; n bigint;
BEGIN
 y:=extract(year from CURRENT_DATE)::integer-CASE WHEN extract(month from CURRENT_DATE)<4 THEN 1 ELSE 0 END;
 fy:=right(y::text,2)||'-'||right((y+1)::text,2);
 INSERT INTO garments_erp.document_number_counter AS c(document_type,financial_year,last_number)
 VALUES('SCPO',fy,1)
 ON CONFLICT(document_type,financial_year) DO UPDATE SET last_number=c.last_number+1
 RETURNING last_number INTO n;
 IF n>9999 THEN RAISE EXCEPTION 'Raw material PO capacity exceeded for %',fy; END IF;
 RETURN 'SCPO/'||lpad(n::text,4,'0')||'/'||fy;
END;
$function$
;
