create view garments_erp.view_default_lab_dip_version with (security_invoker=true) as  SELECT DISTINCT ON (l.color_map_by_brand_id, l.dyer_id) l.color_map_by_brand_id,
    l.dyer_id,
    l.id AS lab_dip_id,
    l.edition,
    v.id AS lab_dip_version_id,
    v.version,
    v.date,
    s.status
   FROM garments_erp.lab_dip l
     JOIN garments_erp.lab_dip_version v ON v.lab_dip_id = l.id
     JOIN garments_erp.lab_dip_version_status s ON s.id = v.lab_dip_status_id
  WHERE s.sort_order >= 4
  ORDER BY l.color_map_by_brand_id, l.dyer_id, v.date DESC NULLS LAST, l.edition DESC, v.version DESC, v.id DESC;
create view garments_erp.view_knitted_fabric_name with (security_invoker=true) as  SELECT kbi.id,
    kbi.knitting_bill_id,
    kbi.fabric_type_id,
    kbi.yarn_bill_item_id,
    kbi.greige_gsm,
    kbi.billed_rate,
    kbi.consumption,
    kbi.billed_quantity,
    kbi.billed_rolls,
    kbi.fabric_status_list_id,
    kbi.created_at,
    yt.id AS yarn_type_id,
    yt.name AS yarn_type_name,
    yt.yarn_count,
    ft.name AS fabric_type_name,
        CASE
            WHEN NULLIF(btrim(yt.yarn_count), ''::text) IS NOT NULL AND NULLIF(btrim(ft.name), ''::text) IS NOT NULL THEN (btrim(yt.yarn_count) || ' '::text) || btrim(ft.name)
            ELSE NULL::text
        END AS fabric_name
   FROM garments_erp.knitting_bill_item kbi
     LEFT JOIN garments_erp.yarn_bill_item ybi ON ybi.id = kbi.yarn_bill_item_id
     LEFT JOIN garments_erp.yarn_purchase_order_item ypoi ON ypoi.id = ybi.yarn_purchase_order_item_id
     LEFT JOIN garments_erp.yarn_type yt ON yt.id = ypoi.yarn_type_id
     LEFT JOIN garments_erp.fabric_type ft ON ft.id = kbi.fabric_type_id;
create view garments_erp.view_variant_item_lab_dip_status with (security_invoker=true) as  SELECT vi.id,
    vi.id AS variant_item_id,
    pc.id AS production_checklist_id,
    vi.lab_dip_id,
    l.edition,
    v.id AS lab_dip_version_id,
    v.version,
    s.status AS version_status,
        CASE
            WHEN vi.lab_dip_id IS NULL THEN 'Lab dip not selected'::text
            WHEN v.id IS NULL THEN 'No versions yet'::text
            WHEN s.id IS NULL THEN 'Status not recorded'::text
            WHEN v.version > 1 AND s.sort_order <= 3 THEN (('Redo '::text || v.version::text) || ' · '::text) || s.status
            ELSE s.status
        END AS lab_dip_status
   FROM garments_erp.variant_item vi
     JOIN garments_erp.item_part ip ON ip.id = vi.item_part_id
     LEFT JOIN garments_erp.production_checklist pc ON pc.item_id = ip.item_id
     LEFT JOIN garments_erp.lab_dip l ON l.id = vi.lab_dip_id
     LEFT JOIN LATERAL ( SELECT vv.id,
            vv.lab_dip_id,
            vv.version,
            vv.date,
            vv.shade_card_no,
            vv.shade_card_option,
            vv.comments,
            vv.shade_card_image_attachment,
            vv.lab_dip_status_id,
            vv.attached_swatch,
            vv.created_at
           FROM garments_erp.lab_dip_version vv
          WHERE vv.lab_dip_id = l.id
          ORDER BY vv.version DESC
         LIMIT 1) v ON true
     LEFT JOIN garments_erp.lab_dip_version_status s ON s.id = v.lab_dip_status_id;
